import 'package:family_veda/models/vital.dart';
import 'package:family_veda/providers/active_member_provider.dart';
import 'package:family_veda/providers/core_providers.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

class VitalEntryScreen extends ConsumerStatefulWidget {
  const VitalEntryScreen({super.key, this.initialKind});

  /// Measurement chosen on the Vitals tab; null opens the free-form entry.
  final VitalKind? initialKind;

  @override
  ConsumerState<VitalEntryScreen> createState() => _VitalEntryScreenState();
}

class _VitalEntryScreenState extends ConsumerState<VitalEntryScreen> {
  final _formKey = GlobalKey<FormState>();
  final _type = TextEditingController();
  final _unit = TextEditingController();
  final _values = <String, TextEditingController>{};
  VitalPreset? _preset;
  bool _saving = false;
  String? _message;

  @override
  void initState() {
    super.initState();
    _preset = vitalPresets
        .where((preset) => preset.kind == widget.initialKind)
        .firstOrNull;
  }

  @override
  void dispose() {
    _type.dispose();
    _unit.dispose();
    for (final controller in _values.values) {
      controller.dispose();
    }
    super.dispose();
  }

  TextEditingController _valueFor(String key) =>
      _values.putIfAbsent(key, TextEditingController.new);

  @override
  Widget build(BuildContext context) {
    final preset = _preset;
    return Scaffold(
      appBar: AppBar(title: const Text('Record vital')),
      body: SafeArea(
        child: Form(
          key: _formKey,
          child: ListView(
            padding: const EdgeInsets.all(16),
            children: [
              const Text(
                'Record the measured value only. Family Veda does not interpret it as a diagnosis.',
              ),
              const SizedBox(height: 16),
              DropdownButtonFormField<VitalPreset?>(
                initialValue: preset,
                isExpanded: true,
                decoration: const InputDecoration(labelText: 'Measurement'),
                items: [
                  for (final item in vitalPresets)
                    DropdownMenuItem(value: item, child: Text(item.label)),
                  const DropdownMenuItem(
                    value: null,
                    child: Text('Other measurement'),
                  ),
                ],
                onChanged: (value) => setState(() => _preset = value),
              ),
              const SizedBox(height: 12),
              if (preset == null) ...[
                TextFormField(
                  controller: _type,
                  decoration: const InputDecoration(labelText: 'Vital type'),
                  maxLength: 60,
                  validator: _required,
                ),
                _numberField('value', 'Value'),
                TextFormField(
                  controller: _unit,
                  decoration: const InputDecoration(labelText: 'Unit'),
                  maxLength: 20,
                  validator: _required,
                ),
              ] else
                for (final field in preset.fields.entries) ...[
                  _numberField(field.key, '${field.value} (${preset.unit})'),
                  const SizedBox(height: 12),
                ],
              const SizedBox(height: 8),
              FilledButton(
                onPressed: _saving ? null : _save,
                child: Text(_saving ? 'Saving…' : 'Save vital'),
              ),
              if (_message != null) ...[
                const SizedBox(height: 16),
                Text(_message!),
              ],
            ],
          ),
        ),
      ),
    );
  }

  Widget _numberField(String key, String label) => TextFormField(
    controller: _valueFor(key),
    decoration: InputDecoration(labelText: label),
    keyboardType: const TextInputType.numberWithOptions(decimal: true),
    validator: (value) {
      final number = double.tryParse(value ?? '');
      return number == null || number < 0 ? 'Enter a numeric value.' : null;
    },
  );

  String? _required(String? value) =>
      value == null || value.trim().isEmpty ? 'Required.' : null;

  Future<void> _save() async {
    if (!_formKey.currentState!.validate()) return;
    final memberId = ref.read(activeMemberProvider);
    if (memberId == null) {
      setState(() => _message = 'Select an active member first.');
      return;
    }
    setState(() {
      _saving = true;
      _message = null;
    });
    final preset = _preset;
    // Blood pressure is two readings; one shared timestamp keeps them paired.
    final measuredAt = DateTime.now();
    final entries = preset == null
        ? [(type: _type.text, key: 'value', unit: _unit.text)]
        : [
            for (final key in preset.fields.keys)
              (type: key, key: key, unit: preset.unit),
          ];
    try {
      for (final entry in entries) {
        await ref
            .read(mobileApiProvider)
            .addVital(
              memberId: memberId,
              vitalType: entry.type,
              value: double.parse(_valueFor(entry.key).text),
              unit: entry.unit,
              measuredAt: measuredAt,
            );
      }
      if (mounted) Navigator.of(context).pop();
    } catch (_) {
      if (mounted) {
        setState(
          () => _message =
              'Vital could not be saved. Check the connection and try again.',
        );
      }
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }
}
